import re
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []
        self.current_row = []
        self.current_data = ""
        self.in_td = False

    def handle_starttag(self, tag, attrs):
        if tag == 'td' or tag == 'th':
            self.in_td = True
            self.current_data = ""

    def handle_endtag(self, tag):
        if tag == 'td' or tag == 'th':
            self.current_row.append(self.current_data.strip())
            self.in_td = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
                self.current_row = []

    def handle_data(self, data):
        if self.in_td:
            self.current_data += data

# Read and parse each file
files = [
    ("1948", "/app/resources/treasury_bulletin_1948_03_page_28.txt"),
    ("1949", "/app/resources/treasury_bulletin_1949_03_page_29.txt"),
    ("1950", "/app/resources/treasury_bulletin_1950_03_page_31.txt"),
    ("1951", "/app/resources/treasury_bulletin_1951_03_page_32.txt"),
]

for year, filepath in files:
    print(f"\n=== January 31, {year} ===")
    with open(filepath, 'r') as f:
        content = f.read()

    parser = TableParser()
    parser.feed(content)

    # Find rows with "Total" and look at the first few columns
    for i, row in enumerate(parser.rows):
        row_str = ' | '.join(row[:6])  # First 6 columns
        if 'Total' in row_str and year in row_str:
            print(f"Row {i}: {row_str}")
        elif 'Total' in row_str:
            # Print all Total rows to see the structure
            print(f"Row {i}: {row_str}")
