# Let me verify my data extraction from each file
from html.parser import HTMLParser

class TableParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.rows = []
        self.current_row = []
        self.current_data = ""
        self.in_td = False

    def handle_starttag(self, tag, attrs):
        if tag == 'td' or tag == 'th':
            self.in_td = True
            self.current_data = ""

    def handle_endtag(self, tag):
        if tag == 'td' or tag == 'th':
            self.current_row.append(self.current_data.strip())
            self.in_td = False
        elif tag == 'tr':
            if self.current_row:
                self.rows.append(self.current_row)
                self.current_row = []

    def handle_data(self, data):
        if self.in_td:
            self.current_data += data

# Verify each year's data
files_info = [
    ("1948", "/app/resources/treasury_bulletin_1948_03_page_28.txt", 1948),
    ("1949", "/app/resources/treasury_bulletin_1949_03_page_29.txt", 1949),
    ("1950", "/app/resources/treasury_bulletin_1950_03_page_31.txt", 1950),
    ("1951", "/app/resources/treasury_bulletin_1951_03_page_32.txt", 1951),
]

print("Data verification:")
print("=" * 60)

for year_label, filepath, expected_year in files_info:
    with open(filepath, 'r') as f:
        content = f.read()

    parser = TableParser()
    parser.feed(content)

    # Find the year header and the next Total row
    year_row_idx = None
    for i, row in enumerate(parser.rows):
        if len(row) > 0 and row[0] == str(expected_year):
            year_row_idx = i
            break

    if year_row_idx is not None:
        for i in range(year_row_idx + 1, len(parser.rows)):
            row = parser.rows[i]
            if len(row) > 2 and 'Total' in ' '.join(row[:3]):
                fixed_maturity = row[2]
                print(f"Jan 31, {expected_year}: {fixed_maturity} million = {float(fixed_maturity.replace(',',''))/1000:.1f} billion")
                break
